-- 更新物品的随机属性ID
-- 给白装替换随机附魔
update item_template set RandomProperty=30004 where  Quality=1 and RandomProperty=0 and RandomSuffix=0 and ItemLevel>4 and ItemLevel<21  and entry<70000 and class in(2,4) and InventoryType not in(0,4,19);
update item_template set RandomProperty=30003 where  Quality=1 and RandomProperty=0 and RandomSuffix=0 and ItemLevel>20 and ItemLevel<30 and entry<70000 and class in(2,4) and InventoryType not in(0,4,19);
update item_template set RandomProperty=30002 where  Quality=1 and RandomProperty=0 and RandomSuffix=0 and ItemLevel>29 and ItemLevel<51 and entry<70000 and class in(2,4) and InventoryType not in(0,4,19);
update item_template set RandomProperty=30001 where  Quality=1 and RandomProperty=0 and RandomSuffix=0 and ItemLevel>50 and ItemLevel<61 and entry<70000  and class in(2,4) and InventoryType not in(0,4,19);

-- 把所有蓝色品质以上、物品等级5-29、没有随机属性的、原始世界的、装备和武器，更新RandomProperty 为30003
update item_template set RandomProperty=30003  where RandomProperty=0 and RandomSuffix=0 and Quality>2 and ItemLevel>4 and ItemLevel<30 and entry<70000 and class in(2,4);

-- 把所有蓝色品质以上、物品等级30-50、没有随机属性的、原始世界的、装备和武器，更新RandomProperty 为30002
update item_template set RandomProperty=30002  where RandomProperty=0 and RandomSuffix=0 and Quality>2 and ItemLevel>29 and ItemLevel<51 and entry<70000 and class in(2,4);

-- 把所有蓝色品质以上、物品等级50以上、没有随机属性的、原始世界的、装备和武器，更新RandomProperty 为30001
update item_template set RandomProperty=30001  where RandomProperty=0 and RandomSuffix=0 and Quality>2 and Quality<4 and ItemLevel>50 and ItemLevel<101 and entry<70000 and class in(2,4);

-- 更新所有60+等级紫装的随机附魔
-- 更新所有60-75装备等级紫装的随机附魔为30005
-- 更新所有76-85装备等级紫装的随机附魔为30006
-- 更新所有86-100（60最高装等100）装备等级紫装的随机附魔为30007

update item_template set RandomProperty=30005 where Quality>3 and RandomSuffix=0  and ItemLevel>60 and ItemLevel<76 and entry<70000 and class in(2,4) and InventoryType not in(0,4,19);
update item_template set RandomProperty=30006 where Quality>3 and RandomSuffix=0  and ItemLevel>75 and ItemLevel<86 and entry<70000 and class in(2,4) and InventoryType not in(0,4,19);
update item_template set RandomProperty=30007 where Quality>3 and RandomSuffix=0  and ItemLevel>85 and ItemLevel<101 and entry<70000  and class in(2,4) and InventoryType not in(0,4,19);

-- 把所有绿装增加随机附魔，3档，30003、30002、30001
update item_template set RandomProperty=30003    where RandomProperty=0 and RandomSuffix=0 and quality=2 and ItemLevel>4 and ItemLevel<30 and entry<30000 and class in(2,4) and InventoryType not in(0,4,19);
update item_template set RandomProperty=30002    where RandomProperty=0 and RandomSuffix=0 and quality=2 and ItemLevel>29 and ItemLevel<51 and entry<30000 and class in(2,4) and InventoryType not in(0,4,19);
update item_template set RandomProperty=30001    where RandomProperty=0 and RandomSuffix=0 and quality=2 and ItemLevel>50 and ItemLevel<101 and entry<30000 and class in(2,4) and InventoryType not in(0,4,19);

-- 漏了这部分装备的随机属性，进行修复，把所有蓝色品质以上、物品等级50-60的、没有随机属性的、原始世界的、装备和武器，更新RandomProperty 为30001
-- select * from item_template where RandomProperty=0 and RandomSuffix=0 and Quality>3 and ItemLevel>50 and ItemLevel<61 and entry<70000 and class in(2,4);
update item_template set RandomProperty=30001  where RandomProperty=0 and RandomSuffix=0 and Quality>3 and ItemLevel>50 and ItemLevel<61 and entry<70000 and class in(2,4);


